specials = {
    BasicBlock: quant.quant_block.QuantBasicBlock,
    Bottleneck: quant.quant_block.QuantBottleneck,
    ResBottleneckBlock: quant.quant_block.QuantResBottleneckBlock,
    InvertedResidual: quant.quant_block.QuantInvertedResidual,
