}

class QuantModel(nn.Module):
    def __init__(
        self, model: nn.Module, weight_quant_params: dict = {}, act_quant_params: dict = {}
    ):
        super().__init__()
        quant.fold_bn.search_fold_and_remove_bn(model)
        self.model = model
        self.quant_module_refactor(self.model, weight_quant_params, act_quant_params)

    def quant_module_refactor(
        self, module: nn.Module, weight_quant_params: dict = {}, act_quant_params: dict = {}
    ):
        prev_quantmodule = None
        for name, child_module in module.named_children():
            if type(child_module) in specials:
                setattr(
                    module, name, specials[type(child_module)](
                        child_module, weight_quant_params, act_quant_params
                    ),
                )
            elif isinstance(child_module, (nn.Conv2d, nn.Linear)):
                setattr(
                    module, name,
                    QuantModule(child_module, weight_quant_params, act_quant_params),
                )
                prev_quantmodule = getattr(module, name)

            elif isinstance(child_module, (nn.ReLU, nn.ReLU6)):
                if prev_quantmodule is not None:
                    prev_quantmodule.activation_function = child_module
                    setattr(module, name, quant.quant_layer.StraightThrough())
                else:
                    continue

            elif isinstance(child_module, quant.quant_layer.StraightThrough):
                continue

            else:
                self.quant_module_refactor(
                    child_module, weight_quant_params, act_quant_params
                )

    def set_quant_state(self, weight_quant: bool = False, act_quant: bool = False):
        for m in self.model.modules():
            if isinstance(m, (QuantModule, BaseQuantBlock)):
                m.set_quant_state(weight_quant, act_quant)

    def forward(self, *args, **kwargs):
        if len(args)==1 and type(args[0]) in [tuple,list]:
            return self.model(*args[0])
        else:
            return self.model(*args, **kwargs)

    def set_first_last_layer_to_8bit(self):
        w_list, a_list = [], []
        for module in self.model.modules():
            if isinstance(module, UniformAffineQuantizer):
                if module.leaf_param:
                    a_list.append(module)
                else:
                    w_list.append(module)
        w_list[0].bitwidth_refactor(8)
        w_list[-1].bitwidth_refactor(8)
        a_list[-2].bitwidth_refactor(8)

    def disable_network_output_quantization(self):
        module_list = []
        for m in self.model.modules():
            if isinstance(m, QuantModule):
                module_list += [m]
        module_list[-1].disable_act_quant = True

def set_weight_quantize_params(model):
    for name, module in model.named_modules():
        if isinstance(module, QuantModule):
            module.weight_quantizer.set_inited(False)
            module.weight_quantizer(module.weight)
            module.weight_quantizer.set_inited(True)


def act_get_quant_state(order, awq):
    if order == "before":
        weight_quant, act_quant = False, True
    elif order == "after":
        weight_quant, act_quant = awq, True
    elif order == "together":
        weight_quant, act_quant = True, True
    else:
        raise NotImplementedError
    return weight_quant, act_quant

def set_act_quantize_params(
    module: BaseQuantBlock,
    cali_data,
    awq: bool = False,
    order: str = "before",
    batch_size: int = 256,
):
    weight_quant, act_quant = act_get_quant_state(order, awq)
    module.set_quant_state(weight_quant, act_quant)
    for t in module.modules():
        if isinstance(t, (QuantModule, BaseQuantBlock)):
            t.act_quantizer.set_inited(False)
    if not isinstance(cali_data, (tuple, list)):
        batch_size = min(batch_size, cali_data.size(0))
        with torch.no_grad():
            for i in range(int(cali_data.size(0) / batch_size)):
                module(cali_data[i * batch_size : (i + 1) * batch_size].cuda())
        torch.cuda.empty_cache()
        for t in module.modules():
            if isinstance(t, (QuantModule, BaseQuantBlock)):
                t.act_quantizer.set_inited(True)
    else:
        batch_size = min(batch_size, cali_data[0].size(0))
        with torch.no_grad():
            for i in range(int(cali_data[0].size(0) / batch_size)):
                module(
                    *[
                        _[i * batch_size : (i + 1) * batch_size].cuda()
                        for _ in cali_data
                    ]
                )
        torch.cuda.empty_cache()
        for t in module.modules():
            if isinstance(t, (QuantModule, BaseQuantBlock)):
                t.act_quantizer.set_inited(True)


def get_init(
    model, block, cali_data, wq, aq, batch_size, input_prob: bool = False, keep_gpu: bool = True,
):
    from QDrop.quant.data_utils import save_inp_oup_data # Deferred import
    cached_inps, cached_outs = save_inp_oup_data(
        model, block, cali_data, wq, aq, batch_size, input_prob=input_prob, keep_gpu=keep_gpu,
    )
    return cached_inps, cached_outs


def layer_reconstruction(model: QuantModel, layer: QuantModule, cali_data: torch.Tensor,
                         batch_size: int = 32, iters: int = 20000, weight: float = 0.001, opt_mode: str = 'mse',
                         act_quant: bool = False, b_range: tuple = (20, 2),
                         warmup: float = 0.0, p: float = 2.0, lr: float = 4e-5, wwq: bool = True, waq: bool = True,
                         order: str = 'together', input_prob: float = 1.0, keep_gpu: bool = True):
    cached_inps, cached_outs = get_init(model, layer, cali_data, wq=wwq, aq=waq, batch_size=batch_size,
                                        input_prob=True, keep_gpu=keep_gpu)
    if act_quant and order == 'together':
        set_act_quantize_params(layer, cali_data=cached_inps[0][:min(256, cached_inps[0].size(0))], awq=True, order=order)
    cur_weight, cur_act = quant.set_weight_quantize_params.weight_get_quant_state(order, act_quant)
    layer.set_quant_state(cur_weight, cur_act)
    round_mode = 'learned_hard_sigmoid'
    w_para, a_para = [], []
    layer.weight_quantizer = AdaRoundQuantizer(uaq=layer.weight_quantizer, round_mode=round_mode,
                                               weight_tensor=layer.org_weight.data)
    layer.weight_quantizer.soft_targets = True
    w_para += [layer.weight_quantizer.alpha]
    if act_quant and order == 'together' and layer.act_quantizer.delta is not None:
        layer.act_quantizer.delta = torch.nn.Parameter(torch.tensor(layer.act_quantizer.delta))
        a_para += [layer.act_quantizer.delta]
    layer.act_quantizer.is_training = True
    w_opt = torch.optim.Adam(w_para) if len(w_para) != 0 else None
    a_opt = torch.optim.Adam(a_para, lr=lr) if len(a_para) != 0 else None
    a_scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(a_opt, T_max=iters, eta_min=0.) if a_opt else None
    loss_mode = 'relaxation'
    rec_loss = opt_mode
    loss_func = LossFunction(layer, round_loss=loss_mode, weight=weight,
                             max_count=iters, rec_loss=rec_loss, b_range=b_range,
                             decay_start=0, warmup=warmup, p=p)
    device = 'cuda'
    sz = cached_inps[0].size(0)
    for i in range(iters):
        idx = torch.randint(0, sz, (batch_size,))
        cur_inp, cur_sym = cached_inps[0][idx].to(device), cached_inps[1][idx].to(device)
        if input_prob < 1.0:
            cur_inp = torch.where(torch.rand_like(cur_inp) < input_prob, cur_inp, cur_sym)
        cur_out = cached_outs[idx].to(device)
        w_opt.zero_grad() if w_opt else None
        a_opt.zero_grad() if a_opt else None
        out_quant = layer(cur_inp)
        err = loss_func(out_quant, cur_out)
        err.backward(retain_graph=True)
        w_opt.step() if w_opt else None
        a_opt.step() if a_opt else None
        a_scheduler.step() if a_scheduler else None
    torch.cuda.empty_cache()
    layer.weight_quantizer.soft_targets = False
    layer.act_quantizer.is_training = False
    if act_quant and order == 'after' and waq:
        set_act_quantize_params(layer, cached_inps[0], awq=True, order=order)


def block_reconstruction(model: QuantModel, block: BaseQuantBlock, cali_data: torch.Tensor,
                         batch_size: int = 32, iters: int = 20000, weight: float = 0.01, opt_mode: str = 'mse',
                         act_quant: bool = False, b_range: tuple = (20, 2),
                         warmup: float = 0.0, p: float = 2.0, lr: float = 4e-5, wwq: bool = True, waq: bool = True,
                         order: str = 'together', input_prob: float = 1.0, keep_gpu: bool = True):
    cached_inps, cached_outs = get_init(model, block, cali_data, wq=wwq, aq=waq, batch_size=batch_size, input_prob=True, keep_gpu=keep_gpu)
    if act_quant and order == 'together':
        set_act_quantize_params(block, cali_data=cached_inps[0][:min(256, cached_inps[0].size(0))], awq=True, order=order)
    cur_weight, cur_act = quant.set_weight_quantize_params.weight_get_quant_state(order, act_quant)
    block.set_quant_state(cur_weight, cur_act)
    round_mode = 'learned_hard_sigmoid'
    w_para, a_para = [], []
    for module in block.modules():
        if isinstance(module, QuantModule):
            module.weight_quantizer = AdaRoundQuantizer(uaq=module.weight_quantizer, round_mode=round_mode,
                                                        weight_tensor=module.org_weight.data)
            module.weight_quantizer.soft_targets = True
            w_para += [module.weight_quantizer.alpha]
        if isinstance(module, (QuantModule, BaseQuantBlock)):
            if act_quant and order == 'together' and module.act_quantizer.delta is not None:
                module.act_quantizer.delta = torch.nn.Parameter(torch.tensor(module.act_quantizer.delta))
                a_para += [module.act_quantizer.delta]
            module.act_quantizer.is_training = True
    w_opt = torch.optim.Adam(w_para) if len(w_para) != 0 else None
    a_opt = torch.optim.Adam(a_para, lr=lr) if len(a_para) != 0 else None
    a_scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(a_opt, T_max=iters, eta_min=0.) if a_opt else None
    loss_mode = 'relaxation'
    rec_loss = opt_mode
    loss_func = LossFunction(block, round_loss=loss_mode, weight=weight, max_count=iters, rec_loss=rec_loss,
                             b_range=b_range, decay_start=0, warmup=warmup, p=p)
    device = 'cuda'
    sz = cached_inps[0].size(0)
    for i in range(iters):
        idx = torch.randint(0, sz, (batch_size,))
        cur_inp, cur_sym = cached_inps[0][idx].to(device), cached_inps[1][idx].to(device)
        if input_prob < 1.0:
            cur_inp = torch.where(torch.rand_like(cur_inp) < input_prob, cur_inp, cur_sym)
        cur_out = cached_outs[idx].to(device)
        w_opt.zero_grad() if w_opt else None
        a_opt.zero_grad() if a_opt else None
        out_quant = block(cur_inp)
        err = loss_func(out_quant, cur_out)
        err.backward(retain_graph=True)
        w_opt.step() if w_opt else None
        a_opt.step() if a_opt else None
        a_scheduler.step() if a_scheduler else None
    torch.cuda.empty_cache()
    for module in block.modules():
        if isinstance(module, QuantModule):
            module.weight_quantizer.soft_targets = False
        if isinstance(module, (QuantModule, BaseQuantBlock)):
            module.act_quantizer.is_training = False
    if act_quant and order == 'after' and waq:
        set_act_quantize_params(block, cached_inps[0], awq=True, order=order)

def quant_model(args, model, diffusion):
    wq_params = {
        "n_bits": args.n_bits_w,
        "channel_wise": args.channel_wise,
        "scale_method": args.init_wmode,
        "symmetric": True,
    }
    aq_params = {
        "n_bits": args.n_bits_a,
        "channel_wise": False,
        "scale_method": args.init_amode,
        "leaf_param": True,
        "prob": args.prob,
        "symmetric": True,
    }
    qnn = QuantModel(
        model=model, weight_quant_params=wq_params, act_quant_params=aq_params
    )
    qnn.cuda()
    qnn.eval()
    if not args.disable_8bit_head_stem:
        qnn.set_first_last_layer_to_8bit()
    qnn.disable_network_output_quantization()
    cali_data = backward_t_calib_data_generator(
        model,
        args,
        args.calib_num_samples,
        "cuda",
        args.calib_t_mode,
        diffusion,
        args.class_cond,
    )
    kwargs = dict(
        cali_data=cali_data,
        iters=args.iters_w,
        weight=args.weight,
        b_range=(args.b_start, args.b_end),
        warmup=args.warmup,
        opt_mode="mse",
        wwq=args.wwq,
        waq=args.waq,
        order=args.order,
        act_quant=args.act_quant,
        lr=args.lr,
        input_prob=args.input_prob,
        keep_gpu=not args.keep_cpu,
    )

    if args.act_quant and args.order == "before" and args.awq is False:
        set_act_quantize_params(
            qnn, cali_data=cali_data, awq=args.awq, order=args.order
        )
    set_weight_quantize_params(qnn)
    if not args.use_adaround:
        set_act_quantize_params(
            qnn, cali_data=cali_data, awq=args.awq, order=args.order
        )
        qnn.set_quant_state(weight_quant=True, act_quant=args.act_quant)
        return qnn
    else:
        def set_weight_act_quantize_params(module):
            if isinstance(module, QuantModule):
                layer_reconstruction(qnn, module, **kwargs)
            elif isinstance(module, BaseQuantBlock):
                block_reconstruction(qnn, module, **kwargs)
            else:
                raise NotImplementedError
        def recon_model(model: nn.Module):
            for name, module in model.named_children():
                if isinstance(module, QuantModule):
                    set_weight_act_quantize_params(module)
                elif isinstance(module, BaseQuantBlock):
                    set_weight_act_quantize_params(module)
                else:
                    recon_model(module)
        recon_model(qnn)
        if args.act_quant and args.order == "after" and args.waq is False:
            set_act_quantize_params(
                qnn, cali_data=cali_data, awq=args.awq, order=args.order
            )
        qnn.set_quant_state(weight_quant=True, act_quant=args.act_quant)
        return qnn

def main():
    parser = argparse.ArgumentParser()
    defaults = dict(
        clip_denoised=True,
        num_samples=10000,
        batch_size=16,
        use_ddim=False,
        model_path="",
    )
    defaults.update(model_and_diffusion_defaults())
    add_dict_to_argparser(parser, defaults)
    parser.add_argument("--data_dir", type=str, help="ImageNet dir")
    parser.add_argument("--seed", default=3, type=int, help="random seed for results reproduction")
    parser.add_argument("--n_bits_w", default=4, type=int, help="bitwidth for weight quantization")
    parser.add_argument("--channel_wise", action="store_true", help="apply channel_wise quantization for weights")
    parser.add_argument("--n_bits_a", default=4, type=int, help="bitwidth for activation quantization")
    parser.add_argument("--act_quant", action="store_true", help="apply activation quantization")
    parser.add_argument("--disable_8bit_head_stem", action="store_true")
    parser.add_argument("--calib_num_samples", default=1024, type=int, help="size of the calibration dataset")
    parser.add_argument("--iters_w", default=20000, type=int, help="number of iteration for adaround")
    parser.add_argument("--weight", default=0.01, type=float, help="weight of rounding cost vs the reconstruction loss.")
    parser.add_argument("--keep_cpu", action="store_true", help="keep the calibration data on cpu")
    parser.add_argument("--wwq", action="store_true", help="weight_quant for input in weight reconstruction")
    parser.add_argument("--waq", action="store_true", help="act_quant for input in weight reconstruction")
    parser.add_argument("--b_start", default=20, type=int, help="temperature at the beginning of calibration")
    parser.add_argument("--b_end", default=2, type=int, help="temperature at the end of calibration")
    parser.add_argument("--warmup", default=0.2, type=float, help="in the warmup period no regularization is applied")
    parser.add_argument("--lr", default=4e-5, type=float, help="learning rate for LSQ")
    parser.add_argument("--awq", action="store_true", help="weight_quant for input in activation reconstruction")
    parser.add_argument("--aaq", action="store_true", help="act_quant for input in activation reconstruction")
    parser.add_argument("--init_wmode", default="mse", type=str, choices=["minmax", "mse", "minmax_scale"], help="init opt mode for weight")
    parser.add_argument("--init_amode", default="mse", type=str, choices=["minmax", "mse", "minmax_scale"], help="init opt mode for activation")
    parser.add_argument("--order", default="before", type=str, choices=["before", "after", "together"], help="order about activation compare to weight")
    parser.add_argument("--prob", default=1.0, type=float)
    parser.add_argument("--input_prob", default=1.0, type=float)
    parser.add_argument("--use_adaround", action="store_true")
    parser.add_argument("--calib_im_mode", default="random", type=str, choices=["random", "raw", "raw_forward_t", "noise_backward_t"])
    parser.add_argument("--calib_t_mode", default="normal", type=str, choices=["random", "1", "-1", "mean", "uniform", "manual", "normal", "poisson"])
    parser.add_argument("--calib_t_mode_normal_mean", default=0.5, type=float, help='for adjusting the weights in the normal distribution')
    parser.add_argument("--calib_t_mode_normal_std", default=0.35, type=float, help='for adjusting the weights in the normal distribution')
    parser.add_argument("--out_path", default="", type=str)

    args = parser.parse_args()

    logger.configure()

    model, diffusion = create_model_and_diffusion(
        **args_to_dict(args, model_and_diffusion_defaults().keys())
    )
    model.load_state_dict(torch.load(args.model_path, map_location="cpu"))
    model.cuda()
    model.eval()

    model = quant_model(args, model, diffusion)

    logger.log("sampling...")
    all_images = []
    all_labels = []
    while len(all_images) * args.batch_size < args.num_samples:
        model_kwargs = {}
        if args.class_cond:
            classes = th.randint(
                low=0, high=NUM_CLASSES, size=(args.batch_size,), device="cuda"
            )
            model_kwargs["y"] = classes
        sample_fn = (
            diffusion.p_sample_loop if not args.use_ddim else diffusion.ddim_sample_loop
        )
        sample = sample_fn(
            model,
            (args.batch_size, 3, args.image_size, args.image_size),
            clip_denoised=args.clip_denoised,
            model_kwargs=model_kwargs,
        )
        sample = ((sample + 1) * 127.5).clamp(0, 255).to(th.uint8)
        sample = sample.permute(0, 2, 3, 1)
        sample = sample.contiguous()
        gathered_samples = sample.unsqueeze(0)
        all_images.extend([sample.cpu().numpy() for sample in gathered_samples])
        if args.class_cond:
            gathered_labels = classes.unsqueeze(0)
            all_labels.extend([labels.cpu().numpy() for labels in gathered_labels])
        logger.log(f"created {len(all_images) * args.batch_size} samples")

        arr = np.concatenate(all_images, axis=0)
        arr = arr[: args.num_samples]
        if args.class_cond:
            label_arr = np.concatenate(all_labels, axis=0)
            label_arr = label_arr[: args.num_samples]
        if 1:
            shape_str = "x".join([str(x) for x in arr.shape[2:]])
            if args.out_path == "":
                out_path = f"outputs/samples_{args.calib_im_mode}_{args.calib_t_mode}_{shape_str}_{args.calib_num_samples}.npz"
            else:
                out_path = args.out_path
            logger.log(f"saving to {out_path}")
            if args.class_cond:
                np.savez(out_path, arr, label_arr)
            else:
                np.savez(out_path, arr)

    logger.log("sampling complete")

if __name__ == "__main__":
    main()
